import XCTest
@testable import SiliconBuddy

/// The mirrored types, checked against the Mac's own export.
///
/// `contract/` is generated by silicon-optimizer's `ContractExportTests` — the shapes
/// its wire types actually encode, not something written by hand here. Each file holds
/// a route: its request, its response, the events it can send and the errors it can
/// answer. The round trip is the part that matters: decode, re-encode, compare the
/// JSON. A field this app forgot to mirror disappears in the re-encode, so the
/// comparison fails — which is the drift that would otherwise be discovered by a
/// person staring at a blank row.
final class ContractTests: XCTestCase {

    // MARK: - Fixtures

    private func fixture(_ name: String) throws -> [String: JSONValue] {
        let bundle = Bundle(for: ContractTests.self)
        let url = try XCTUnwrap(
            bundle.url(forResource: name, withExtension: "json", subdirectory: "contract")
                ?? bundle.url(forResource: name, withExtension: "json"),
            "Missing fixture \(name).json — run contract/refresh.sh"
        )
        let value = try JSONValue(data: try Data(contentsOf: url))
        guard case .object(let fields) = value else {
            throw XCTSkip("\(name).json is not a route fixture")
        }
        return fields
    }

    /// Decodes one part of a fixture — `response`, `request`, or one named event — then
    /// re-encodes it and compares field by field.
    @discardableResult
    private func roundTrip<T: Codable & Equatable>(
        _ type: T.Type, _ name: String, _ part: String = "response",
        file: StaticString = #filePath, line: UInt = #line
    ) throws -> T {
        let fields = try fixture(name)
        let piece: JSONValue
        if part.hasPrefix("events.") {
            let event = String(part.dropFirst("events.".count))
            piece = try XCTUnwrap(
                fields["events"]?[event], "\(name) has no \(part)", file: file, line: line
            )
        } else if part.hasPrefix("errors.") {
            let status = String(part.dropFirst("errors.".count))
            piece = try XCTUnwrap(
                fields["errors"]?[status], "\(name) has no \(part)", file: file, line: line
            )
        } else {
            piece = try XCTUnwrap(fields[part], "\(name) has no \(part)", file: file, line: line)
        }

        let data = try JSONEncoder().encode(piece)
        let decoded: T
        do {
            decoded = try JSONDecoder.buddy.decode(type, from: data)
        } catch {
            XCTFail("\(name).\(part) does not decode as \(type): \(error)", file: file, line: line)
            throw error
        }
        let reencoded = try JSONEncoder.buddy.encode(decoded)
        XCTAssertEqual(
            decoded, try JSONDecoder.buddy.decode(type, from: reencoded),
            "\(name).\(part) changed shape on a round trip", file: file, line: line
        )

        let original = piece.strippingNulls()
        let rebuilt = try JSONValue(data: reencoded).strippingNulls()
        if original != rebuilt {
            XCTFail(
                "\(name).\(part) lost or changed fields on a round trip:\n"
                    + original.difference(from: rebuilt).joined(separator: "\n"),
                file: file, line: line
            )
        }
        return decoded
    }

