    func testTheContractIsTheWholeExportAndNothingElse() throws {
        let bundle = Bundle(for: ContractTests.self)
        let directory = try XCTUnwrap(
            bundle.url(forResource: "contract", withExtension: nil) ?? bundle.resourceURL
        )
        let files = try FileManager.default.contentsOfDirectory(
            at: directory, includingPropertiesForKeys: nil
        )
        let fixtures = Set(
            files.filter { $0.pathExtension == "json" }
                .map { $0.deletingPathExtension().lastPathComponent }
        )
        let missing = Self.expectedFixtures.subtracting(fixtures).sorted()
        let extra = fixtures.subtracting(Self.expectedFixtures).sorted()
        XCTAssertTrue(
            missing.isEmpty,
            "The contract is missing \(missing.joined(separator: ", ")) — run contract/refresh.sh"
        )
        XCTAssertTrue(
            extra.isEmpty,
            "The Mac grew \(extra.joined(separator: ", ")) — mirror them, then add them here"
        )
        XCTAssertTrue(
            files.contains { $0.lastPathComponent == "routes.md" },
            "routes.md comes with the export"
        )
    }

    /// Every status any route documents has a case of its own. A new one falling into
    /// `.server` would reach a person as a number.
    func testEveryDocumentedStatusIsMapped() throws {
        var seen: Set<Int> = []
        for name in Self.expectedFixtures.sorted() {
            let fields = try fixture(name)
            guard case .object(let errors)? = fields["errors"] else { continue }
            for (status, body) in errors {
                let code = try XCTUnwrap(Int(status))
                seen.insert(code)
                let mapped = TransportError.from(
                    status: code, body: try JSONEncoder().encode(body), path: "/x"
                )
                let error = try XCTUnwrap(mapped, "\(name) documents \(code); nothing maps it")
                if case .server(let number, _) = error {
                    XCTFail("\(name) documents \(number) and it falls through to .server")
                }
                XCTAssertFalse(
                    (error.errorDescription ?? "").isEmpty,
                    "\(name) \(code) reaches a person as nothing"
                )
            }
        }
        XCTAssertEqual(
            seen, [400, 401, 403, 404, 409, 411, 413, 429],
            "The statuses the Mac documents changed — run contract/refresh.sh, then map them"
        )
    }

    /// Three things the current export says that an older copy did not. A stale
    /// contract/ fails here rather than being discovered on a phone.
    func testTheExportIsTheCurrentOne() throws {
        for name in Self.expectedFixtures.sorted() where name.hasPrefix("POST__") {
            // Every POST but the three that take no body at all documents a 400.
            guard !["POST__benchmark", "POST__unload", "POST__jev_calibrate"].contains(name)
            else { continue }
            let fields = try fixture(name)
            guard case .object(let errors)? = fields["errors"] else {
                return XCTFail("\(name) documents no errors at all")
            }
            XCTAssertNotNil(errors["400"], "\(name) should document a 400 — refresh the contract")
        }
        for name in ["GET__recommend", "GET__conversations__id_", "DELETE__buddy_devices__id_"] {
            let fields = try fixture(name)
            guard case .object(let errors)? = fields["errors"] else { continue }
            XCTAssertNotNil(errors["404"], "\(name) should document a 404 — refresh the contract")
        }
        for name in ["POST__chat_stream", "POST__conversations__id__messages", "GET__events"] {
            let fields = try fixture(name)
            guard case .object(let errors)? = fields["errors"] else { continue }
            XCTAssertNotNil(errors["429"], "\(name) should document a 429 — refresh the contract")
        }
    }

    // MARK: - Errors

    func testEveryErrorBodyInTheContractDecodes() throws {
        let bundle = Bundle(for: ContractTests.self)
        let directory = bundle.url(forResource: "contract", withExtension: nil)
        let urls = try FileManager.default.contentsOfDirectory(
            at: directory ?? bundle.bundleURL, includingPropertiesForKeys: nil
        ).filter { $0.pathExtension == "json" }
        XCTAssertGreaterThan(urls.count, 20, "The contract export should be here")

        var checked = 0
        for url in urls {
            guard case .object(let fields) = try JSONValue(data: try Data(contentsOf: url)),
                  case .object(let errors)? = fields["errors"]
            else { continue }
            for (status, body) in errors {
                let data = try JSONEncoder().encode(body)
                let decoded = try JSONDecoder.buddy.decode(ControlAPI.ErrorResponse.self, from: data)
                XCTAssertFalse(
                    decoded.error.isEmpty,
                    "\(url.lastPathComponent) \(status) has an empty message"
                )
                // And the mapping has somewhere to put it.
                let mapped = TransportError.from(
                    status: Int(status) ?? 0, body: data, path: "/x"
                )
                XCTAssertNotNil(mapped, "\(status) should map to an error")
                checked += 1
            }
        }
        XCTAssertGreaterThan(checked, 30, "Every route lists the errors it can answer")
    }

    /// A chat-scope device asking to load a model gets this, and it is not the same
    /// thing as "your token is wrong".
    func testTheScopeRefusalIsNotAnUnpairing() throws {
        let fields = try fixture("POST__load")
        let body = try JSONEncoder().encode(try XCTUnwrap(fields["errors"]?["403"]))
        let error = TransportError.from(status: 403, body: body, path: "/load")
        guard case .forbidden(let message)? = error else {
            return XCTFail("403 should be its own case, not unauthorized")
        }
        XCTAssertTrue(message.contains("chat only"))
        XCTAssertNotEqual(error, .unauthorized)
    }

    // MARK: - Requests this app builds

    func testRequestsEncodeTheWayTheMacReadsThem() throws {
        let load = ControlAPI.LoadRequest(modelID: "bonsai-2-27b", quantization: "PTQ1_0")
        let json = try JSONValue(data: JSONEncoder.buddy.encode(load))
        XCTAssertEqual(json["modelID"], .string("bonsai-2-27b"))
        XCTAssertNil(json["contextLength"], "Absent options must not be sent as null")
    }

    func testANewMessageCarriesContentNotATranscript() throws {
        let request = BuddyAPI.NewMessageRequest(
            content: "What is this?", images: ["data:image/jpeg;base64,AAA"], maxTokens: 2048
        )
        let json = try JSONValue(data: JSONEncoder.buddy.encode(request))
        XCTAssertEqual(json["content"], .string("What is this?"))
        XCTAssertEqual(json["images"]?[0], .string("data:image/jpeg;base64,AAA"))
        XCTAssertEqual(json["maxTokens"], .number(2048))
        XCTAssertNil(json["messages"], "The Mac has the history; this route takes one message")
    }

    func testAnEmptyImageListIsStillSent() throws {
        let request = ControlAPI.ChatRequest(messages: [.init(role: "user", content: "hi")])
        let json = try JSONValue(data: JSONEncoder.buddy.encode(request))
        XCTAssertEqual(json["messages"]?[0]?["images"], .array([]))
    }

    // MARK: - Decoding is forgiving where the Mac says it may be

    func testAStatusFromAnOlderMacStillDecodes() throws {
        let json = Data(#"{"state":"Not loaded","expertStreaming":false}"#.utf8)
        let status = try JSONDecoder.buddy.decode(ControlAPI.Status.self, from: json)
        XCTAssertFalse(status.hasLoadedModel)
    }

    func testAPairResponseWithoutAScopeMeansFull() throws {
        let json = Data(#"{"deviceID":"1","token":"t","macName":"Mac","port":8788}"#.utf8)
        let paired = try JSONDecoder.buddy.decode(BuddyAPI.PairResponse.self, from: json)
        XCTAssertNil(paired.scope)
        XCTAssertEqual(BuddyAPI.DeviceScope(wire: paired.scope), .full)
    }

    func testConversationTimestampsDecodeBothISOSpellings() throws {
        let withFraction = Data(#"{"id":"1","title":"t","updatedAt":"2026-09-18T10:11:12.345Z","messageCount":2}"#.utf8)
        let plain = Data(#"{"id":"1","title":"t","updatedAt":"2026-09-18T10:11:12Z","messageCount":2}"#.utf8)
        XCTAssertNoThrow(try JSONDecoder.buddy.decode(BuddyAPI.ConversationSummary.self, from: withFraction))
        XCTAssertNoThrow(try JSONDecoder.buddy.decode(BuddyAPI.ConversationSummary.self, from: plain))
    }
